/* Portable browser-data backup validation and merge. No executable content is imported. */
(function(root){'use strict';const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),str=x=>typeof x==='string',arr=(x,label)=>{if(!Array.isArray(x)||x.length>10000)throw Error('Invalid '+label);return x;};
function validate(value){if(!obj(value)||value.format!=='flightdesk-backup'||value.version!==1||!obj(value.profiles)||value.profiles.version!==1||!obj(value.flights)||value.flights.version!==1)throw Error('Use a complete Flightdesk backup file (version 1).');const p=value.profiles;
for(const name of ['pilots','operators'])for(const r of arr(p[name],name)){if(!obj(r)||!str(r.key)||!str(r.name)||!str(r.registration)||!str(r.expiry))throw Error('Invalid crew profile');}
for(const name of ['batteries','removedBatteries']){const list=name==='removedBatteries'?(p[name]||[]):p[name];for(const r of arr(list,name)){if(!obj(r)||!str(r.key)||!str(r.name)||!str(r.type)||!(r.soc===null||Number.isFinite(r.soc))||!Number.isInteger(r.units)||!str(r.health)||!str(r.inspection))throw Error('Invalid battery record');}}
for(const r of arr(p.batteryChanges||[],'battery changes')){if(!obj(r)||!str(r.key)||!Array.isArray(r.spreads)||!r.spreads.every(v=>v===null||Number.isFinite(v))||!str(r.failedKey)||!str(r.failedName)||!str(r.failedAt))throw Error('Invalid battery history');if(r.readings!==undefined&&(!Array.isArray(r.readings)||!r.readings.every(obj)))throw Error('Invalid battery readings');}
for(const r of arr(value.flights.records,'flight records')){if(!obj(r)||r.schemaVersion!==1||!str(r.id)||!str(r.projectTitle)||!str(r.missionTitle)||!str(r.savedAt)||!obj(r.values)||!obj(r.readiness)||typeof r.readiness.go!=='boolean'||!str(r.readiness.scope)||!Array.isArray(r.checks)||!r.checks.every(obj)||!Array.isArray(r.cellReadings)||!r.cellReadings.every(obj)||!Array.isArray(r.batteryChanges))throw Error('Invalid flight snapshot');if(r.site!==null&&r.site!==undefined&&(!obj(r.site)||!Number.isFinite(r.site.lat)||!Number.isFinite(r.site.lon)))throw Error('Invalid saved site');}
if(value.settings!==undefined){if(!obj(value.settings))throw Error('Invalid saved app settings');for(const[k,v]of Object.entries(value.settings))if(!k.startsWith('flightdesk-')||['flightdesk-local-profiles-v1','flightdesk-flight-records-v1'].includes(k)||!str(v))throw Error('Invalid saved app setting');}
return value;}
function merge(existing,incoming,id){const keys=new Set(existing.map(r=>r[id])),result=[...existing];for(const r of incoming)if(!keys.has(r[id])){keys.add(r[id]);result.push(r);}return result;}
function reportHTML(records,exportedAt){
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=r=>r.readiness?.status==='warning'?'WARNING':r.readiness?.go?'GO':'NO-GO';
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flightdesk UK · saved flight records</title><style>body{font:14px/1.5 system-ui,sans-serif;color:#152f3b;max-width:1100px;margin:32px auto;padding:0 20px}h1{font-size:26px}h2{font-size:20px}table{border-collapse:collapse;width:100%;margin:18px 0}th,td{padding:9px;border:1px solid #ccd6dc;text-align:left;vertical-align:top}th{background:#f1f5f7}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.5 monospace;background:#f5f7f8;padding:14px}article{border-top:2px solid #ccd6dc;margin-top:30px;padding-top:12px}@media print{body{margin:0;padding:0}article{break-before:page}tr{break-inside:avoid}pre{font-size:9px}}</style></head><body><h1>Flightdesk UK · saved flight records</h1><p>Exported at '+escape(exportedAt)+' · '+records.length+' saved snapshot(s). All timestamps are shown as recorded; schedule fields use Europe/London.</p><p>Pilot-recorded planning records. Readiness is historical, not independent verification of compliance, flight clearance or proof a flight took place. Multiple snapshots may belong to the same mission. Unsaved form entries are excluded. This report contains personal and site information: review before sharing.</p><p>Use the browser Print / Save as PDF menu for a PDF copy. Keep the separate JSON backup for restoration; this report cannot be imported.</p>'+(records.length?'<table><thead><tr><th>Project / mission</th><th>Saved at</th><th>Take-off · London time</th><th>Aircraft</th><th>Readiness at save</th></tr></thead><tbody>'+records.map(r=>'<tr><td>'+escape(r.projectTitle)+' / '+escape(r.missionTitle)+'</td><td>'+escape(r.savedAt)+'</td><td>'+escape(r.values?.date)+' '+escape(r.values?.hour)+':'+escape(r.values?.startminute||'00')+'</td><td>'+escape(r.values?.aircraft||r.values?.aircraftselect)+'</td><td>'+status(r)+'</td></tr>').join('')+'</tbody></table>':'<p>No saved flight records were present when this report was downloaded.</p>')+records.map((r,i)=>'<article><h2>'+String(i+1)+'. '+escape(r.projectTitle)+' / '+escape(r.missionTitle)+'</h2><p>Snapshot ID: '+escape(r.id)+' · Mission ID: '+escape(r.missionId)+' · Saved: '+escape(r.savedAt)+' · '+status(r)+'</p><h3>Complete saved snapshot</h3><p>Includes the checks, notes, declarations, recorded forecast/airspace evidence and battery information present when saved. Missing information has not been reconstructed.</p><pre>'+escape(JSON.stringify(r,null,2))+'</pre></article>').join('')+'</body></html>';
}
function clearAppStorage(storage){const keys=[];for(let i=0;i<storage.length;i++){const k=storage.key(i);if(k?.startsWith('flightdesk-'))keys.push(k);}for(const k of keys)storage.removeItem(k);for(const k of keys)if(storage.getItem(k)!==null)throw Error('Some app data could not be removed.');return keys.length;}
const api={validate,merge,reportHTML,clearAppStorage};root.FLIGHTDESK_BACKUP=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
